window.docContents[100].resolve({"/Overview/#Cvc___lean----High-Level-CVC5-API--Overview--Simple-check-sat":{"contents":"#eval Env.runIO do\n  let (solver, b1, i1) ← setup\n  println! \"check-sat\"\n  for f in ← solver.getAssertions do println! \"∧ {f}\"\n  solver.checkSat\n    (ifSat := do\n      let b1 ← solver.getValue b1\n      let i1 ← solver.getValue i1\n      println! \"→ sat: b1 ↦ {b1}, i1 ↦ {i1}\")\n\n\ncheck-sat\n∧ (or (not b1) (and b1 (< 0 i1)))\n→ sat: b1 ↦ false, i1 ↦ 0\n\n\n","context":"Cvc.lean -- High-Level CVC5 API\u0009Overview","header":"1.2. Simple check-sat","id":"/Overview/#Cvc___lean----High-Level-CVC5-API--Overview--Simple-check-sat"}});